  add('air','basic','注射器にとじこめた空気を、ピストンでおして、手をはなすと、ピストンは、どうなりますか。','もとの位置にもどる',['そのままとまる','もっとおされる','外れる'],['おしちぢめられた空気は、もとにもどろうとします。','手ごたえを思い出しましょう。'],'手をはなすと、空気がもとの大きさにもどろうとして、ピストンもおしもどされます。');
  add('air','basic','もののかさ（場所をしめる大きさ）のことを、何といいますか。','体積',['重さ','温度','長さ'],['ものが、場所をどれだけしめるかを表します。','ml や cm³ で表します。'],'ものが場所をしめる大きさを、体積といいます。',null,['体積','たいせき']);

  add('air','standard','100mL の空気を、注射器にとじこめて、おしちぢめたら、80mL になりました。空気の体積は、何mL 小さくなりましたか。',20,[80,180,100],['はじめの体積から、おしたあとの体積を引きます。','100－80を計算します。'],'100－80＝20。体積は20mL 小さくなりました。');
  add('air','standard','100mL の空気を、50mL までおしちぢめても、空気の重さは、どうなりますか。','かわらない',['半分になる','２倍になる','なくなる'],['空気の量は、かわりましたか。','体積は小さくなっても、空気の量は、同じです。'],'空気の体積は小さくなっても、空気の量はかわらないので、重さもかわりません。',null,['かわらない','変わらない']);
  add('air','standard','空気を入れた注射器と、水を入れた注射器を、それぞれピストンでおしました。おしちぢめにくいのは、どちらですか。','水',['空気','どちらも同じ','どちらもおしちぢめられる'],['水の体積は、おしてもほとんどかわりません。','空気は、おしちぢめられます。'],'水はおしても体積がほとんどかわらず、おしちぢめにくいです。空気はおしちぢめられます。',null,['水','みず']);
  add('air','standard','とじこめた空気を、強くおすほど、空気の体積は、どうなりますか。','小さくなる',['大きくなる','かわらない','重くなる'],['力を大きくすると、どうなるでしょう。','手ごたえの大きさも、考えましょう。'],'強くおすほど、空気の体積は小さくなります。',null,['小さくなる','ちいさくなる','ちぢむ','縮む']);
  add('air','standard','ペットボトルにふたをして、強くおすと、ふたが飛びました。ふたが飛んだのは、どうしてですか。','中の空気が、もとにもどろうとして、ふたをおしたから',['水が、ふたをおしたから','ふたが、軽かったから','外の空気が、中に入ったから'],['空気がおしちぢめられました。','おしちぢめられた空気は、どうなろうとしますか。'],'おしちぢめられた空気が、もとの大きさにもどろうとして、ふたをおし出しました。');
  add('air','standard','空のコップをさかさまにして、水の中にしずめると、水は、どうなりますか。','少ししか入らない',['すぐにいっぱいになる','コップがういてしまう','全く入らない'],['コップの中には、空気がありました。','空気の体積は、おしちぢめられます。'],'コップの中の空気が、水が入るのをさまたげるので、少ししか入りません。',null,['少ししか入らない','少しだけ入る','すこししかはいらない']);
  add('air','standard','空気鉄ぽうの玉を、もっと遠くまで、飛ばすには、おし棒を、どのようにおしますか。','強くおす',['弱くおす','おさずにまつ','ゆっくりおす'],['空気を、より強くおしちぢめると、どうなりますか。','もとにもどろうとする力が、大きくなります。'],'強くおすほど、空気はよりおしちぢめられ、もとにもどろうとする力が大きくなって、玉は遠くまで飛びます。');
  add('air','standard','空気を風船に入れると、ふくらみます。これは、空気が、どうするからですか。','風船の中から、ふくろをおし広げるから',['風船の中から出ていくから','風船の外から、おしつぶすから','空気が重くなるから'],['空気には、おしちぢめると、もとにもどろうとする力があります。','風船の中の空気は、風船のかべを、どうしますか。'],'空気は、とじこめられたふくろの中で、かべをおし広げようとするので、風船はふくらみます。');
  add('air','standard','100mLの水を、注射器に入れて、ピストンをおしても、体積は何mLのままですか。',100,[50,80,200],['水は、おしちぢめても、体積がほとんどかわりません。','おす前と、体積は同じです。'],'水は、おしちぢめても、体積がほとんどかわらないので、100mLのままです。');
  add('air','standard','空気と水を、注射器に半分ずつ入れて、ピストンをおしました。体積が小さくなったのは、どちらですか。','空気',['水','両方','どちらも小さくならない'],['水は、おしちぢめられません。','おしちぢめられるのは、どちらですか。'],'おしちぢめられるのは空気です。水の体積はほとんどかわりません。',null,['空気','くうき']);
  add('air','standard','おしちぢめられて、小さくなった空気が、もとにもどろうとして、おし返す力を、手で感じるのは、どのようなときですか。','注射器のピストンを、おしたとき',['注射器を、ふったとき','注射器を、水に入れたとき','注射器を、冷やしたとき'],['空気を、おしちぢめるときです。','手ごたえを、感じます。'],'ピストンをおして、空気をおしちぢめるとき、空気がおし返す力を手ごたえとして感じます。');
  add('air','standard','おもちゃのボールの空気をぬくと、へこみます。これは、ボールの中の空気が、どうなったからですか。','ぬけて、へったから',['重くなったから','ふえたから','色がかわったから'],['ボールの中の空気は、ボールのかべを、内側から、おしていました。','空気がへると、おす力は、どうなりますか。'],'空気がへると、ボールのかべを内側からおす力が小さくなり、ボールがへこみます。');
  add('air','standard','空気でっぽうで、前の玉が飛び出す直前、前の玉と後ろの玉の間の空気は、どうなっていますか。','おしちぢめられている',['のびている','なくなっている','かわらない'],['おし棒をおして、空気をとじこめています。','玉が飛び出すのは、空気がもとにもどろうとするからです。'],'おし棒をおすと、玉の間の空気がおしちぢめられます。おしちぢめられた空気が、もとにもどろうとして、前の玉をおし出します。',null,['おしちぢめられている','ちぢんでいる','縮んでいる','小さくなっている']);
  add('air','standard','空気を入れた自転車のタイヤが、かたいのは、どうしてですか。','中の空気が、タイヤを内側からおしているから',['タイヤの中が、空だから','タイヤの中に、水が入っているから','タイヤが、重いから'],['空気は、とじこめられると、おし返す力をもちます。','タイヤの中の空気は、おしちぢめられています。'],'おしちぢめられた空気が、タイヤを内側からおしているので、タイヤがかたくなります。');

  add('air','advanced','注射器に、空気50mL と水50mL を入れて、ピストンをおしたら、全体が90mL になりました。縮んだのは、何mLですか。',10,[50,90,100],['全体の体積から、おしたあとの体積を引きます。','縮んだのは、空気だけです。'],'100－90＝10。体積は10mL縮みました。縮んだのは空気だけで、空気の体積は40mLになりました。');
  add('air','advanced','注射器に、空気50mL と水50mL を入れて、ピストンをおしました。水の体積は、何mLのままですか。',50,[40,25,100],['水は、おしても、体積がほとんどかわりません。','空気が縮みます。'],'水は、おしても体積がほとんどかわらないので、50mLのままです。');
  add('air','advanced','密閉した注射器の中に、風船を入れて、ピストンをおすと、風船は、どうなりますか。','小さくなる',['大きくなる','かわらない','われる'],['風船の外の空気が、おしちぢめられます。','外の空気の力が、風船をおします。'],'注射器の中の空気がおしちぢめられると、外から風船をおす力が大きくなり、風船は小さくなります。',null,['小さくなる','ちいさくなる','ちぢむ','縮む']);
  add('air','advanced','空気が、おしちぢめられると、体積が小さくなるのは、空気を、どのようなものとして考えられるからですか。','空気は、ものの間にすきまがあり、ちぢむことができるから',['空気は、固体だから','空気は、水と同じだから','空気は、重いだけだから'],['水は、おしても体積があまりかわりません。','空気は、気体です。'],'空気（気体）は、ものの間にすきまがあり、おすと小さくなることができます。');
  add('air','advanced','空のペットボトルのふたを閉めて、ピストンをおしこむように、おすと、ペットボトルは、どうなりますか。','へこむ（形がかわる）',['かわらない','大きくなる','われる'],['ペットボトルの中の空気は、おしちぢめられます。','おす力が、強いとき、どうなりますか。'],'ペットボトルの中の空気が、おしちぢめられるので、ペットボトルはへこみます。');
  add('air','advanced','空気を入れた風船を、強くおすと、われることがあります。この理由として、正しいものはどれですか。','おしちぢめられた空気が、おし返す力が強くなるから',['空気が、なくなるから','空気が、かるくなるから','風船が、あたたまるから'],['空気は、おしちぢめられると、おし返す力が大きくなります。','その力が、風船のゴムの強さを、こえたときです。'],'おしちぢめられた空気のおし返す力が、風船のゴムの強さをこえると、風船はわれます。');
  add('air','advanced','注射器に空気を100mL とじこめて、ピストンをおして、体積が半分になったとき、おし返す力は、はじめと比べて、どうなりますか。','大きくなる',['小さくなる','かわらない','なくなる'],['体積が小さいほど、おし返す力は、どうなりますか。','強くおしたときの、手ごたえを、思い出しましょう。'],'体積が小さくなるほど、空気がおし返す力は大きくなります。',null,['大きくなる','おおきくなる']);
  add('air','advanced','注射器に、水をいっぱい入れて、先を、ふさいで、ピストンをおしました。ピストンは、どうなりますか。','ほとんど動かない',['すぐに奥までおせる','もとにもどってくる','水が、ふえる'],['水は、おしちぢめにくいです。','空気がないときは、どうなりますか。'],'水はほとんどおしちぢめられないので、ピストンはほとんど動きません。');
  add('air','advanced','注射器のピストンを強くおしても、ほとんど動きませんでした。注射器の中に入っているのは、空気と水の、どちらだと考えられますか。','水',['空気','どちらも考えられない','空気と水の両方'],['もとにもどる力は、空気にあります。','水は、おしちぢめても、もどる力がありません。'],'空気はおしちぢめられますが、水はおしちぢめられないので、ピストンがほとんど動かないときは、水が入っていると考えられます。',null,['水','みず']);
  add('air','advanced','暑い日に、ふたを閉めたペットボトルを、日なたに置いておくと、ふくらむことがあります。これは、中の空気が、どうなったからですか。','あたためられて、体積が大きくなったから',['冷やされて、体積が小さくなったから','入れかわったから','重くなったから'],['空気は、あたためると、どうなりますか。','体積の変化を、考えます。'],'空気はあたためられると、体積が大きくなります。ペットボトルの中の空気が体積を大きくして、ペットボトルがふくらみます。');
  add('air','advanced','空気の重さを調べるために、ボールの空気をぬいたり、入れたりして、重さを比べます。重さを調べるのに使うものは、何ですか。','はかり',['温度計','ものさし','ルーペ'],['重さを調べる道具です。','上皿てんびんも、使えます。'],'重さを調べるときは、はかり（上皿てんびん）を使います。',null,['はかり','秤','上皿てんびん','うわざらてんびん']);

  // ---- 水のすがた：基礎7・標準13・発展11（原作の5問を合わせて 9/15/12）----
  add('water','basic','水が、すがたをかえて、目に見えない気体になったものを、何といいますか。','水蒸気',['湯気','氷','雲'],['水を熱し続けると、水は、すがたをかえます。','湯気は、目に見えるもので、水蒸気ではありません。'],'水が気体になったものを、水蒸気（すいじょうき）といいます。水蒸気は目に見えません。',null,['水蒸気','すいじょうき']);
  add('water','basic','やかんの口から出る、白いけむりのようなものを、何といいますか。','湯気',['水蒸気','氷','けむり'],['水蒸気は目に見えません。','白く見えるものは、小さな水のつぶです。'],'湯気は、水蒸気が冷やされて、小さな水のつぶになったものです。目に見えます。',null,['湯気','ゆげ']);
  add('water','basic','水が氷になることを、何といいますか。','こおる',['とける','蒸発する','ふっとうする'],['０℃より冷やすと、どうなりますか。','氷が水になるのは、「とける」です。'],'水が冷やされて氷になることを、こおるといいます。',null,['こおる','凍る','氷る']);
  add('water','basic','氷が水になることを、何といいますか。','とける',['こおる','蒸発する','ふっとうする'],['氷を、あたためると、どうなりますか。','水が氷になるのは、「こおる」です。'],'氷が水になることを、とけるといいます。',null,['とける','溶ける','解ける']);
  add('water','basic','水が、水面から、ゆっくりと水蒸気になって、空気中へ出ていくことを、何といいますか。','蒸発',['ふっとう','こおる','とける'],['水たまりが、いつのまにかなくなります。','100℃より低い温度でも、起こります。'],'水が水面から水蒸気になって、空気中へ出ていくことを、蒸発（じょうはつ）といいます。',null,['蒸発','じょうはつ']);
  add('water','basic','冷たい飲みものを入れたコップの外側に、水てきがつきました。この水は、どこから出てきたものですか。','空気中の水蒸気',['コップの中の飲みもの','コップの水','氷がとけたもの'],['コップの外側は、冷やされています。','空気中には、水蒸気があります。'],'空気中の水蒸気が、冷たいコップにふれて冷やされ、水になって、水てきがつきました。');
  add('water','basic','水の３つのすがたは、固体・液体と、あと１つは、何ですか。','気体',['湯気','雲','水蒸気ガス'],['氷は固体、水は液体です。','水蒸気は、気体です。'],'水は、固体（氷）・液体（水）・気体（水蒸気）の、３つのすがたにかわります。',null,['気体','きたい']);

  add('water','standard','水を熱し続けて、ふっとうしている間、水の温度は、どうなりますか。','かわらない（約100℃のまま）',['どんどん上がる','下がる','ゆっくり上がる'],['ふっとうしている間の温度を、思い出しましょう。','水がふっとうする温度は、およそ100℃です。'],'ふっとうしている間、水の温度は約100℃のままで、かわりません。');
  add('water','standard','氷がとけている間、温度は、何℃のままですか。',0,[10,50,100],['氷がとけて水になる温度です。','水がこおる温度と同じです。'],'氷がとけている間は、温度は０℃のままです。');
  add('water','standard','100gの氷が、とけて水になりました。水の重さは、およそ何gですか。',100,[50,90,200],['すがたがかわっても、ものの量は、かわりません。','重さは、かわるでしょうか。'],'氷がとけて水になっても、ものの量はかわらないので、重さは100gのままです。');
  add('water','standard','水が水蒸気になると、体積は、どうなりますか。','とても大きくなる',['小さくなる','かわらない','なくなる'],['湯気が、出ているとき、やかんの中の水は、へっています。','気体になると、すきまが広がります。'],'水が水蒸気になると、体積はとても大きくなります。');
  add('water','standard','冬の朝、まどガラスの内側が、くもりました。これは、空気中の水蒸気が、どうなったからですか。','冷やされて、水のつぶになったから',['あたためられて、水蒸気になったから','氷になったから','ガラスから、出てきたから'],['まどガラスは、外の冷たい空気で、冷やされています。','水蒸気は、冷やされるとどうなりますか。'],'部屋の中の水蒸気が、冷たいまどガラスにふれて冷やされ、小さな水のつぶになって、くもります。');
  add('water','standard','水を入れた容器に、ふたをしないで、日なたに置いておくと、水は、どうなりますか。','少しずつへる',['かわらない','ふえる','こおる'],['水は、水面から、ゆっくりすがたをかえます。','そのことを、何といいましたか。'],'水が、水面から蒸発して、少しずつへっていきます。');
  add('water','standard','水を熱して、あわが出てきました。このあわの正体は、何ですか。','水蒸気',['空気','湯気','氷'],['水が熱せられて、すがたをかえています。','水の中から、出てきた気体です。'],'ふっとうしているときの、あわの正体は、水が水蒸気になったものです。',null,['水蒸気','すいじょうき']);
  add('water','standard','氷に食塩を混ぜると、温度は、どうなりますか。','０℃より低くなる',['０℃より高くなる','０℃のままかわらない','100℃になる'],['氷と食塩を混ぜたとき、温度計で調べる実験があります。','氷に食塩を混ぜると、とても冷たくなります。'],'氷に食塩を混ぜると、０℃より低い温度になります。');
  add('water','standard','水を熱して、ふっとうしてから、さらに熱し続けると、水の量は、どうなりますか。','へる',['ふえる','かわらない','全部氷になる'],['ふっとうしている水は、水蒸気になっていきます。','水蒸気は、空気中に出ていきます。'],'ふっとうしている間、水はどんどん水蒸気になるので、水の量はへります。',null,['へる','減る','少なくなる']);
  add('water','standard','洗たくものが、かわくのは、水が、どうなるからですか。','水蒸気になって、空気中へ出ていくから',['水が、氷になるから','水が、布にしみこむから','水が、ふっとうするから'],['洗たくものの水は、空気中へ出ていきます。','水が、水蒸気になることを、何といいましたか。'],'洗たくものの水は、蒸発して水蒸気になり、空気中へ出ていきます。そのため、かわきます。');
  add('water','standard','水を冷やして氷にすると、体積は、どうなりますか。','大きくなる',['小さくなる','かわらない','なくなる'],['ペットボトルに水を入れて、冷凍庫に入れると、どうなりますか。','氷は、水にうきます。'],'水が氷になると、体積は大きくなります。そのため、氷は水にうきます。',null,['大きくなる','ふえる','増える']);
  add('water','standard','氷が水にういているのは、同じ重さで比べたとき、氷の体積が、水より、どうだからですか。','大きいから',['小さいから','かわらないから','重いから'],['同じ重さなら、体積が大きいほうが、かるいといえます。','氷の体積は、水が氷になると、どうなりますか。'],'同じ重さで、氷のほうが体積が大きいので、水にうきます。',null,['大きい','おおきい']);
  add('water','standard','ふっとうしているやかんの口の、すぐそばには、湯気が見えません。これは、口のすぐそばは、何だからですか。','水蒸気で、目に見えないから',['氷で、目に見えないから','空気で、何もないから','熱くて、湯気が消えるから'],['やかんの中から出てくるのは、水蒸気です。','湯気は、水蒸気が冷やされたものです。'],'やかんの口のすぐそばは水蒸気のままで、目に見えません。少しはなれて冷やされると、小さな水のつぶになり、湯気として見えます。');

  add('water','advanced','ビーカーの水を熱して、ふっとうしたあと、ビーカーの上に冷たいガラス板を、かぶせました。ガラス板の内側には、何がつきますか。','水てき',['氷','水蒸気','あわ'],['ふっとうして出た水蒸気は、ガラス板で冷やされます。','冷やされた水蒸気は、どうなりますか。'],'水蒸気が、冷たいガラス板で冷やされて、水になるため、水てきがつきます。',null,['水てき','水滴','すいてき']);
  add('water','advanced','水を熱して、温度をはかり続けたとき、ふっとうしてから、ずっと温度がかわらないのは、加えられた熱が、何に使われるからですか。','水を水蒸気にかえることに使われるから',['水を氷にかえることに使われるから','空気をあたためることだけに使われるから','何にも使われないから'],['ふっとうしている間、水はすがたをかえています。','温度がかわらなくても、水はへっています。'],'ふっとうしている間は、加えた熱が、水が水蒸気にかわることに使われるので、温度は上がりません。');
  add('water','advanced','ふっとうしていなくても、水が水蒸気になることを何といいますか。','蒸発',['ふっとう','とける','こおる'],['水たまりがなくなる、洗たくものがかわく、などの場面です。','100℃より低くても、起こります。'],'ふっとうしていなくても、水が水面から水蒸気になることを、蒸発といいます。',null,['蒸発','じょうはつ']);
  add('water','advanced','日なたと日かげに、同じ量の水を入れた容器を置いておきました。水が早くへるのは、どちらですか。','日なた',['日かげ','どちらも同じ','どちらもへらない'],['温度が高いほど、蒸発しやすいです。','日なたの水は、あたためられます。'],'日なたは温度が高くなるので、水が蒸発しやすく、早くへります。',null,['日なた','ひなた']);
  add('water','advanced','水を入れたビーカーに、ふたをして、あたためると、ふたの内側が、くもりました。ビーカーの中の水蒸気は、どうなりましたか。','ふたで冷やされて、水になった',['氷になった','なくなった','空気になった'],['水は、蒸発して、水蒸気になります。','水蒸気は、冷やされると、どうなりますか。'],'水が蒸発してできた水蒸気が、冷たいふたにふれて冷やされ、水てきになって、ふたの内側にくっつきます。');
  add('water','advanced','氷水（氷を入れた水）の中に、温度計を入れて、そのまま置いておくと、氷が少しとけてきました。そのとき、水の温度は、およそ何℃ですか。',0,[10,5,100],['氷がとけている間の温度は、かわりません。','氷が、とけはじめる温度です。'],'氷が、水にとけている間は、温度はおよそ０℃のままです。');
  add('water','advanced','100℃より高い温度で、水の、すがたは、何ですか。','気体（水蒸気）',['液体','固体','氷'],['水がふっとうする温度は、約100℃です。','ふっとう点より高いと、水は、どうなりますか。'],'100℃をこえると、水は水蒸気（気体）になります。');
  add('water','advanced','水を、ふっとうさせるとき、ふっとう石を入れるのは、どうしてですか。','急にふっとうして、湯がとびはねるのを防ぐため',['水を、冷やすため','水の重さを、はかるため','水をにごらせるため'],['ふっとうするとき、急に、あわが出て、あぶないことがあります。','ガラス器具を使うときに、起こることです。'],'ふっとう石は、湯が急にふっとうして、とびはねるのを防ぎます。');
  add('water','advanced','水を熱して、ふっとうさせたら、あわが、ブクブクと出ました。そのあわを、つめたいビニールぶくろで、おおうと、ふくろの内側に、何がつきましたか。','水てき',['氷','空気','何もつかない'],['あわは、水が、すがたをかえたものでした。','水蒸気は、冷やされると、どうなりますか。'],'あわの正体の水蒸気が、冷たいふくろで冷やされて、水になりました。',null,['水てき','水滴','すいてき']);
  add('water','advanced','水が水蒸気になって空気中に出ていくこと、水蒸気が水にもどること、水が氷になること、のうち、「熱をうばわれる」ことで起こるのは、どれですか。','水蒸気が水になること、水が氷になること',['水が水蒸気になること','氷が水になること','どれも熱を加えたときに起こる'],['水蒸気が水に、水が氷に、なるときは、どうなりますか。','冷やされるときに起こることを、選びます。'],'水蒸気が水になる、水が氷になる、は冷やされるときに起こります。水が水蒸気になる、氷が水になる、は熱を加えたときに起こります。');
  add('water','advanced','水・氷・水蒸気を、体積の大きい順にならべたとき、正しいものは、どれですか。（同じ重さで比べます）','水蒸気、氷、水',['氷、水、水蒸気','水、氷、水蒸気','水蒸気、水、氷'],['水蒸気の体積は、とても大きいです。','氷は、水にうきます。'],'同じ重さで比べると、水蒸気がもっとも大きく、次が氷、いちばん小さいのが水です。');

  // ---- ものの温度とあたたまり方：基礎8・標準13・発展11（原作の4問を合わせて 9/15/12）----
  add('heat','basic','温度計で温度をはかるとき、目もりは、どの向きから読みますか。','真横から',['真上から','真下から','ななめ上から'],['目の高さを、液面と、同じにします。','ななめから見ると、読みちがえます。'],'温度計の目もりは、液の先と目の高さを同じにして、真横から読みます。',null,['真横','まよこ','真横から','まよこから']);
  add('heat','basic','温度計の、液だめ（下の丸い部分）に、手でふれてはいけない理由は、何ですか。','手の温度が、つたわってしまうから',['温度計が、こわれるから','目もりが、消えるから','液だめが、よごれるから'],['液だめに、手がふれると、手の温度が、つたわります。','正しい温度が、はかれなくなります。'],'手の温度が、液だめにつたわり、正しい温度をはかれないので、手でふれてはいけません。');
  add('heat','basic','水をあたためると、あたたまった水は、上と下の、どちらへ動きますか。','上',['下','横','動かない'],['あたたまった水は、軽くなります。','あたたまり方を、思い出しましょう。'],'あたためられた水は上へ動き、上のほうの冷たい水が、下へ動いて、全体があたたまります。',null,['上','うえ']);
  add('heat','basic','金属の、ぼうのはしを熱すると、熱は、どのようにつたわりますか。','熱したところから、順に、つたわる',['ぼう全体に、同時につたわる','熱したところと反対側から、つたわる','つたわらない'],['金属は、熱したところから、はなれるほど、おそくあたたまります。','熱が、順につたわっていきます。'],'金属は、熱したところから、順に熱がつたわり、あたたまります。');
  add('heat','basic','空気をあたためると、空気の体積は、どうなりますか。','大きくなる',['小さくなる','かわらない','なくなる'],['ふたをした試験管を、あたためると、どうなりますか。','あたためると、広がります。'],'空気は、あたためると、体積が大きくなります。',null,['大きくなる','おおきくなる','ふえる','増える']);
  add('heat','basic','空気を冷やすと、空気の体積は、どうなりますか。','小さくなる',['大きくなる','かわらない','なくなる'],['へこんだボールを、あたためると、もとにもどります。','冷やすと、ちぢみます。'],'空気は冷やすと、体積が小さくなります。',null,['小さくなる','ちいさくなる','ちぢむ','縮む']);
  add('heat','basic','金属の球を熱すると、体積は、どうなりますか。','わずかに大きくなる',['大きく小さくなる','かわらない','なくなる'],['金属も、熱すると、のびます。','変化は、とても小さいです。'],'金属は、熱すると体積がわずかに大きくなります。',null,['大きくなる','わずかに大きくなる','おおきくなる']);
  add('heat','basic','ガラスのくだに、水を入れて、熱すると、水面は、どうなりますか。','上がる',['下がる','かわらない','なくなる'],['水を、あたためると、体積は、どうなりますか。','体積が大きくなると、水面が、上がります。'],'水は、あたためると体積が大きくなるので、水面が上がります。',null,['上がる','あがる']);

  add('heat','standard','金属・水・空気を、同じようにあたためたとき、体積が、いちばん大きくふえるのは、何ですか。','空気',['金属','水','どれも同じ'],['体積の変化が大きいのは、気体です。','金属は、わずかにふえます。'],'あたためたとき、体積の変化は、空気がもっとも大きく、次が水、金属の変化がもっとも小さいです。',null,['空気','くうき']);
  add('heat','standard','金属・水・空気を、冷やしたとき、体積の変化がいちばん小さいのは、何ですか。','金属',['水','空気','どれも同じ'],['体積の変化が小さいのは、固体です。','空気は、体積が大きく変わります。'],'冷やしたとき、体積の変化は、金属がもっとも小さく、次が水、空気がもっとも大きいです。',null,['金属','きんぞく']);
  add('heat','standard','金属の輪を、ぴったり通る金属の球があります。球だけを熱したあと、輪を通そうとすると、どうなりますか。','通らなくなる',['すぐに通る','もっとかんたんに通る','かわらない'],['熱すると、金属の体積は、どうなりますか。','球が、わずかに大きくなります。'],'球を熱すると、体積がわずかに大きくなるので、輪を通らなくなります。',null,['通らなくなる','とおらなくなる','通らない','とおらない']);
  add('heat','standard','熱した金属の球を、冷やしたら、また輪を、通るようになりました。これは、球の体積が、どうなったからですか。','小さくなって、もとにもどったから',['大きくなったから','かわらなかったから','なくなったから'],['熱すると、大きくなりました。','冷やすと、どうなりますか。'],'冷やすと体積が小さくなってもとにもどったので、輪を通れるようになりました。');
  add('heat','standard','へこんだピンポン玉を、お湯に入れると、もとにもどることがあります。これは、中の空気が、どうなったからですか。','あたためられて、体積が大きくなったから',['冷やされたから','なくなったから','重くなったから'],['空気は、あたためられると、体積が大きくなります。','ピンポン玉の中の空気が、おし出します。'],'ピンポン玉の中の空気が、お湯であたためられて体積が大きくなり、へこみをおし出して、もとにもどります。');
  add('heat','standard','ふたをした試験管の口に、せっけん水のまくをはって、試験管を、お湯の中に入れました。まくは、どうなりますか。','ふくらむ',['へこむ','かわらない','われる'],['試験管の中の空気は、あたためられます。','空気の体積は、どうなりますか。'],'試験管の中の空気があたためられて、体積が大きくなり、まくをおし上げるので、ふくらみます。',null,['ふくらむ']);
  add('heat','standard','ふたをした試験管の口に、せっけん水のまくをはって、試験管を、氷水の中に入れました。まくは、どうなりますか。','へこむ',['ふくらむ','かわらない','われる'],['試験管の中の空気は、冷やされます。','冷やすと、空気の体積は、どうなりますか。'],'試験管の中の空気が冷やされて、体積が小さくなり、まくが、へこみます。',null,['へこむ']);
  add('heat','standard','水を入れたビーカーを、下から熱します。水は、どのようにあたたまりますか。','あたたまった水が上へ動いて、全体があたたまる',['熱した所だけが、あたたまる','上のほうだけが、あたたまる','下のほうだけが、あたたまる'],['あたためられた水は、軽くなります。','水が、動いてあたたまります。'],'あたためられた水が上へ動き、上の冷たい水が下へ動くことをくり返して、全体があたたまります。');
  add('heat','standard','部屋をストーブであたためると、あたたかい空気は、どこに集まりますか。','部屋の上のほう',['部屋の下のほう','部屋の真ん中だけ','かべのそば'],['あたためられた空気は、軽くなります。','水のあたたまり方と同じです。'],'あたためられた空気は軽くなって上へ動くので、部屋の上のほうにあたたかい空気が集まります。',null,['上のほう','うえのほう','上','うえ']);
  add('heat','standard','エアコンで、部屋をあたためるとき、あたたかい風は、どの向きに出すと、よいですか。','下向き',['上向き','横向き','どの向きでも同じ'],['あたたかい空気は、上へ動きます。','部屋の下のほうを、あたためたいときは、どうしますか。'],'あたたかい空気は上へ動くので、暖房のときは風を下向きに出すと、部屋全体があたたまりやすいです。',null,['下向き','したむき','下','した']);
  add('heat','standard','かん詰のふたを、あたためて、開けやすくするとき、ふたの金属は、どうなりますか。','体積が大きくなって、ゆるむ',['体積が小さくなる','かわらない','かたくなる'],['金属は、熱すると、どうなりますか。','ふたが、びんの口より、大きくなります。'],'金属のふたを熱すると、体積がわずかに大きくなって、ゆるむので、開けやすくなります。');
  add('heat','standard','ふっとうしているお湯の温度は、およそ何℃ですか。',100,[50,80,200],['水が、ふっとうする温度を思い出しましょう。','水蒸気に、なる温度です。'],'ふっとうしているお湯の温度は、およそ100℃です。');
  add('heat','standard','水を熱し始める前の温度は20℃でした。熱し始めて５分後に40℃になりました。ふっとうするまで同じ割合で上がるとして、10分後は何℃ですか。',60,[50,80,100],['５分ごとに、何℃ずつ上がっていますか。','20℃上がるのに、５分かかっています。'],'５分で20℃ずつ上がるので、10分後は 20＋20＋20＝60℃です。');

  add('heat','advanced','温度計を、お湯につけて、目もりを読みました。液面が、ちょうど「45」のところに、ありました。温度は、何℃ですか。',45,[44,55,40],['液面と同じ目もりを読みます。','目もりは、真横から読みます。'],'液面が45の目もりにあるので、温度は45℃です。');
  add('heat','advanced','金属の板の、はしを熱したとき、熱したところから遠いところまで、熱がつたわる、といえるのは、何のはたらきですか。','熱が、金属の中を、順につたわっていくこと',['金属が、動いて、熱をはこぶこと','熱が空気を通って、つたわること','金属が、あたたまると、軽くなること'],['金属は、熱したところから順にあたたまります。','金属が、動くわけではありません。'],'金属は、熱したところから順に、熱がつたわっていきます。');
  add('heat','advanced','水が、あたためられると動くようすを、調べるために、ビーカーの水に、何を入れると、水の動きがわかりやすくなりますか。','みそや、おがくずなどの小さなつぶ',['砂糖','食塩','氷'],['水の動きを、目で見えるようにしたいのです。','水といっしょに動く、小さなつぶです。'],'みそなどの小さなつぶを入れると、水といっしょに動くので、水の動きが見えます。');
  add('heat','advanced','ふたをした試験管の口に、せっけん水のまくをはって、手でにぎったら、まくがふくらみました。これは、手の何が、試験管の中の空気に、つたわったからですか。','熱',['光','音','力'],['手は、あたたかいです。','空気の体積が、大きくなりました。'],'手の熱が試験管の中の空気につたわって、あたためられ、体積が大きくなって、まくがふくらみます。',null,['熱','ねつ']);
  add('heat','advanced','とけない、ぴったりしまったびんのふたを、お湯につけると、あけやすくなることがあります。これは、ふたが、何になるためですか。','体積が大きくなるため',['体積が小さくなるため','軽くなるため','かたくなるため'],['金属は、熱すると、どうなりますか。','お湯は、熱いです。'],'金属のふたがお湯であたためられて体積がわずかに大きくなり、ゆるんで、あけやすくなります。');
  add('heat','advanced','同じ量の水・空気・金属を、同じ温度だけあたためたとき、体積の変化の大きさを、大きい順にならべたものは、どれですか。','空気、水、金属',['金属、水、空気','水、空気、金属','空気、金属、水'],['もっとも変化が大きいのは、気体です。','もっとも変化が小さいのは、固体です。'],'体積の変化は、空気（気体）、水（液体）、金属（固体）の順に大きいです。');
  add('heat','advanced','金属の線路は、夏と冬でつなぎ目に、すきまが、あけてあります。これは、金属が、どうなるからですか。','夏にのびて、冬にちぢむから',['夏にちぢんで、冬にのびるから','ずっと同じ長さだから','何もかわらないから'],['金属は、熱すると、体積が大きくなります。','夏と冬の温度のちがいを、考えます。'],'金属は、暑い夏にはのびて、寒い冬にはちぢむので、つなぎ目にすきまがあけてあります。');
  add('heat','advanced','水を、ビーカーの底の中心でなく、はしを熱したとき、水は、どのように動きますか。','熱したほうが上がり、反対側が下がる',['熱したほうが下がる','動かない','全体が、上へ動く'],['熱せられた水は、軽くなって、上へ動きます。','水は、まわるように動きます。'],'熱せられた水は上へ動き、反対側で冷たい水が、下へ動いて、水が、ぐるぐると回るように動きます。');
  add('heat','advanced','お湯に、ふくろを入れて、口をしばって、水で冷やしました。ふくろは、どうなりますか。','ふくろが、へこむ',['ふくらむ','かわらない','われる'],['ふくろの中の空気は、冷やされます。','冷やされた空気の体積は、どうなりますか。'],'ふくろの中の空気が冷やされて体積が小さくなるので、ふくろはへこみます。');
  add('heat','advanced','金属のぼうを、熱し続けると、熱したところから、はなれた場所に、だんだん熱が、つたわります。この熱のつたわり方を調べるために、ぼうに何をぬっておくと、よいですか。','熱で色がかわるもの（温度で色がかわるインク）',['水','油','砂'],['熱がつたわったところが、見えるようにします。','温度で、色がかわるものがあります。'],'温度で色がかわるものをぬっておくと、熱がつたわったところが、色の変化で見えます。');
  add('heat','advanced','ストーブの前の空気は、あたためられると軽くなります。この空気は、どのように動きますか。','上へ動く',['下へ動く','動かない','横へしか動かない'],['あたためられた水は、上へ動きました。','空気も、同じです。'],'あたためられた空気は軽くなるので、上へ動きます。',null,['上へ動く','うえへうごく','上','うえ']);

  // ---- 季節と生き物：基礎8・標準14・発展12（原作の2問を合わせて 9/15/12）----
  add('season','basic','サクラの花がさく季節は、いつですか。','春',['夏','秋','冬'],['気温が、だんだん高くなる季節です。','入学式のころを、思い出しましょう。'],'サクラの花は、春にさきます。',null,['春','はる']);
  add('season','basic','夏に、気温が高くなると、ヘチマのくきや葉は、どうなりますか。','どんどんのびて、よくしげる',['かれる','ちぢむ','かわらない'],['夏は、植物がよく育つ季節です。','気温が高いと、植物の成長は、どうなりますか。'],'夏は気温が高いので、ヘチマのくきはどんどんのびて、葉もよくしげります。');
  add('season','basic','木の葉が赤や黄色にかわる季節は、いつですか。','秋',['春','夏','冬'],['木の葉が落ちる前の季節です。','気温が、だんだん低くなる季節です。'],'木の葉の色が赤や黄色にかわるのは、秋です。',null,['秋','あき']);
  add('season','basic','カエルは、冬のあいだ、どこですごしますか。','土の中',['水の上','木の上','空の上'],['寒さをさけて、ねむったようにすごします。','動物は、冬の間は、どうやってすごしますか。'],'カエルは、冬のあいだ、土の中や水底で、ほとんど動かずにすごします（冬眠）。',null,['土の中','つちのなか','土']);
  add('season','basic','秋になると、ツバメは、どこへ向かいますか。','あたたかい南の国',['寒い北の国','日本の山','海の中'],['ツバメは、渡り鳥です。','寒くなる前に、あたたかい所へ行きます。'],'ツバメは、秋になると、あたたかい南の国へ渡っていきます。');
  add('season','basic','ヘチマのたねを、まく季節は、いつですか。','春',['夏','秋','冬'],['気温がだんだん高くなる季節です。','芽が出て、のびはじめるころです。'],'ヘチマのたねは、春にまきます。夏に大きく育ち、秋に実がなります。',null,['春','はる']);
  add('season','basic','動物の活動が、さかんになるのは、気温が高い季節と、低い季節の、どちらですか。','気温が高い季節',['気温が低い季節','どちらも同じ','季節は関係ない'],['春から秋にかけて、虫や鳥をよく見かけます。','冬は、どうなっていましたか。'],'気温が高い春から秋は、動物の活動がさかんです。冬は、あまり見かけなくなります。',null,['気温が高い季節','気温が高い','春から秋','あたたかい季節']);
  add('season','basic','カマキリは、冬のあいだ、どんなすがたですごしますか。','卵',['成虫','よう虫','さなぎ'],['カマキリの成虫は、冬の前に、死んでしまいます。','あわのようなものの中に、入っています。'],'カマキリは、秋に卵をうみ、卵のすがたで冬をすごします。',null,['卵','たまご']);

  add('season','standard','冬、木のえだに、ついている、小さな芽を何といいますか。','冬芽',['春芽','秋芽','夏芽'],['冬の間に、えだにできています。','春になると、葉や花になります。'],'冬のえだについている芽を、冬芽（ふゆめ）といいます。春になると、葉や花になります。',null,['冬芽','ふゆめ']);
  add('season','standard','ナナホシテントウは、冬のあいだ、どんなすがたですごしますか。','成虫',['卵','よう虫','さなぎ'],['落ち葉の下などに、集まってすごします。','冬は、えさがとれません。'],'ナナホシテントウは、成虫のすがたで、落ち葉の下などで冬をすごします。',null,['成虫','せいちゅう']);
  add('season','standard','アゲハ（ナミアゲハ）は、冬のあいだ、どんなすがたですごしますか。','さなぎ',['卵','よう虫','成虫'],['アゲハは、完全変態の虫です。','木のえだなどに、くっついています。'],'アゲハは、さなぎのすがたで冬をすごします。春になると、成虫になって出てきます。',null,['さなぎ']);
  add('season','standard','秋に、ヘチマの実が、じゅくしてきました。実の中に、できているものは、何ですか。','たね',['花','葉','根'],['来年、芽を出すための、ものです。','実の中を、思い出しましょう。'],'ヘチマの実の中には、たねができます。来年の春に、また芽を出します。',null,['たね','種']);
  add('season','standard','冬、寒くなると、木の葉が、すっかり落ちる木があります。これを、何といいますか。','落葉樹',['常緑樹','低木','草木'],['葉が落ちるのは、冬の寒さに、たえるためです。','サクラやイチョウが、なかまです。'],'冬に葉を落とす木を落葉樹（らくようじゅ）といいます。サクラやイチョウがなかまです。',null,['落葉樹','らくようじゅ']);
  add('season','standard','ガンやハクチョウは、冬になると、日本にやってきます。このような鳥を、何といいますか。','渡り鳥',['留鳥','野鳥','水鳥'],['寒い国から、やってくる鳥です。','季節によって、すむ場所をかえます。'],'季節によって、すむ場所をかえる鳥を、渡り鳥といいます。ガンやハクチョウは、冬に日本へ渡ってきます。',null,['渡り鳥','わたりどり']);
  add('season','standard','気温が下がる冬、動物の活動は、春や夏とくらべて、どうなりますか。','少なくなる',['さかんになる','かわらない','夜だけさかんになる'],['冬は、えさが少なくなります。','カエルやヘビは、冬眠します。'],'冬は、気温が低く、えさも少ないので、動物の活動は少なくなります。',null,['少なくなる','すくなくなる','へる','減る']);
  add('season','standard','春になって、気温が高くなると、ヘチマのくきは、どうなりますか。','のびはじめる',['かれる','かわらない','ちぢむ'],['気温と、植物の成長の関係を、考えます。','春は、植物が成長を始める季節です。'],'春は気温が高くなるので、ヘチマは芽を出し、くきがのびはじめます。',null,['のびはじめる','のびる','のびていく','成長する']);
  add('season','standard','気温が低くなる秋から冬にかけて、コオロギなどの虫は、どうなりますか。','死んで、卵を残す',['冬眠する','冬も、さかんに鳴く','葉の上で、冬をこす'],['コオロギは、秋に鳴く虫です。','卵のすがたで、冬をこすものが多いです。'],'コオロギなどは、秋に卵をうみ、成虫は冬の前に死んでしまいます。卵が冬をこして、春にふ化します。');
  add('season','standard','季節による生き物の様子を調べるとき、毎回、同じ場所を観察する理由は、何ですか。','変化を、くらべやすいから',['見やすい場所だから','景色が、きれいだから','虫が、多いから'],['同じ場所で調べると、どうなりますか。','前と、くらべます。'],'同じ場所を観察すると、季節による変化をくらべやすく、記録も整理しやすいです。');
  add('season','standard','夏、ヘチマの花は、何色ですか。','黄色',['赤','白','青'],['ヘチマは、おばなとめばなが、さきます。','ヘチマの花は、夏にさきます。'],'ヘチマの花は黄色で、夏にさきます。おばなとめばなが別々にさきます。',null,['黄色','きいろ','黄']);
  add('season','standard','サクラが、春に花をさかせるために、前の年の夏から秋にかけて、準備するものは、何ですか。','花芽',['冬芽の葉','根','たね'],['春に花になる芽は、前の年のうちに、できています。','冬には、えだについています。'],'サクラは、前の年の夏から秋に花芽をつくり、冬をこして、春に花をさかせます。',null,['花芽','はなめ','かが']);
  add('season','standard','秋の終わりに、ヘチマのくきや葉は、どうなりますか。','かれる',['のびる','青くしげる','花がさく'],['気温が、低くなると、植物は、どうなりますか。','夏とくらべて、気温は、どうなっていますか。'],'秋の終わりから冬にかけて気温が低くなると、ヘチマのくきや葉は、かれていきます。',null,['かれる','枯れる']);
  add('season','standard','秋に、木の実をたべて、たくわえ、冬にそなえる動物は、どれですか。','リス',['カエル','ツバメ','トンボ'],['冬の食べものが、少なくなる前に、集めておきます。','木の実を、集める動物です。'],'リスは、秋に、木の実をたくわえて、冬にそなえます。');

  add('season','advanced','ヘチマのくきが、のびる速さを、春・夏・秋で比べると、いちばん速いのは、いつですか。','夏',['春','秋','冬'],['いちばん、気温が高い季節です。','植物は、気温が高いと、よく育ちます。'],'ヘチマは、気温が高い夏に、いちばん速くのびます。',null,['夏','なつ']);
  add('season','advanced','気温が下がると、へびやカエルのような動物が冬眠するのは、どうしてですか。','体温が下がって、活動できなくなるから',['動くのがきらいだから','えさが、多すぎるから','水が、きらいだから'],['カエルやヘビは、まわりの温度で、体の温度がかわります。','寒いと、体が、動かしにくくなります。'],'まわりの温度が下がると、体温も下がって、動けなくなるため、冬眠します。');
  add('season','advanced','気温の高い夏に、アサガオやヘチマの葉が、大きく広がるのは、何をたくさんつくるためですか。','養分',['空気','熱','風'],['葉は、日光を受けとって、何かをつくります。','植物が、成長するために必要なものです。'],'葉は、日光を受けて養分をつくります。夏は日光が強いので、葉が大きく広がり、養分をたくさんつくります。',null,['養分','ようぶん']);
  add('season','advanced','春になって、気温が上がると、冬ごしをしていた、さなぎは、どうなりますか。','成虫になって出てくる',['よう虫にもどる','卵になる','死んでしまう'],['アゲハは、さなぎで冬をこします。','さなぎの中で、体が、かわっています。'],'春に気温が上がると、さなぎの中で成長が進み、成虫になって出てきます。');
  add('season','advanced','季節ごとの、気温と生き物の変化を、1年間記録するとき、観察カードに必ず書くべきものは、どれですか。','日付・天気・気温・様子',['見た人の名前だけ','好きな色だけ','天気だけ'],['あとで、くらべるために、書くものです。','気温と生き物の関係を、調べます。'],'日付・天気・気温・生き物の様子を記録すると、季節ごとの変化を、くらべることができます。');
  add('season','advanced','冬、サクラの木が、葉をすべて落としているのは、どうしてだと考えられますか。','寒さにたえて、養分や水分を、むだにしないため',['花をさかせるため','根が成長するため','太陽に当たりたくないため'],['冬は、日光が弱く、気温も低いです。','冬は、植物の成長が、とまります。'],'冬は日光が弱く、気温も低いので、葉を落として、養分や水分を、むだにしないようにしていると考えられます。');
  add('season','advanced','秋に、サクラの葉が、赤くなってから、落ちます。この後、サクラの木は、冬を、どのようにすごしますか。','冬芽をつけて、冬をこす',['全部かれて、なくなる','根が、冬に成長する','新しい葉が、冬に出る'],['枝に、冬芽がありました。','春になると、芽が成長します。'],'サクラは葉を落とし、冬芽をつけて冬をこして、春に新しい芽を出します。');
  add('season','advanced','ナナホシテントウが、春にあらわれ、アブラムシを食べるのは、何のためですか。','成長して、卵をうむため',['冬眠するため','巣をつくるため','渡るため'],['春から夏は、動物の活動がさかんになります。','アブラムシは、えさです。'],'テントウムシは、春にあたたかくなると活動をはじめ、えさをたくさん食べて成長し、卵をうみます。');
  add('season','advanced','植物の1年を調べたとき、成長が止まるのは、どの季節ですか。','冬',['春','夏','秋'],['気温が、低い季節です。','日光も、弱くなります。'],'冬は、気温が低く、日光も弱いので、植物の成長は止まります。',null,['冬','ふゆ']);
  add('season','advanced','動物が、冬にそなえて、体にたくわえるものは、何ですか。','脂肪',['水','土','空気'],['冬は、えさが、とれなくなります。','体に、たくわえます。'],'クマやリスなどは、秋にたくさん食べて、体に脂肪をたくわえ、冬にそなえます。',null,['脂肪','しぼう','あぶら']);
  add('season','advanced','夏の夜、よく鳴いていた虫が、秋に、鳴かなくなりました。この変化は、何のせいだと考えられますか。','気温が、下がったため',['雨が、ふったため','星が、見えなくなったため','風が、強くなったため'],['夏から秋にかけて、季節がかわります。','虫の活動は、気温で、かわります。'],'秋になって、気温が下がると、虫の活動が少なくなり、鳴かなくなります。');
  add('season','advanced','季節の生き物の変化を調べる方法として、正しいものは、どれですか。','同じ生き物を、1年を通して、記録する',['1日だけ観察する','好きな季節だけ観察する','写真だけをとる'],['季節ごとの変化を、くらべたいのです。','長い期間、観察を続けます。'],'同じ生き物を、1年を通して観察し、記録すると、季節による変化がわかります。');

  // ---- 天気と気温：基礎9・標準13・発展12（原作の2問を合わせて 9/15/12）----
  add('weather','basic','空気の温度のことを、何といいますか。','気温',['水温','地温','体温'],['天気予報で、よく聞くことばです。','単位は ℃ です。'],'空気の温度を、気温（きおん）といいます。',null,['気温','きおん']);
  add('weather','basic','気温をはかるとき、温度計を、どこに置きますか。','風通しのよい日かげ',['日なた','地面の上','建物の中'],['温度計に、日光が当たると、どうなりますか。','空気の温度を、はかります。'],'気温は、温度計に日光が当たらない、風通しのよい日かげではかります。');
  add('weather','basic','気温をはかるとき、地面から、どのくらいの高さではかりますか。','1.2m〜1.5m',['10cm','3m','10m'],['地面の熱の、えいきょうを、さけます。','だいたい、大人の顔の高さです。'],'気温は、地面の熱のえいきょうをさけるため、地面から1.2m〜1.5mの高さではかります。');
  add('weather','basic','気温をはかる、百葉箱の外側は、何色にぬってありますか。','白',['黒','赤','青'],['日光を、はね返す色です。','中の温度が、上がらないようにします。'],'百葉箱は、日光をはね返して中の温度が上がらないように、白くぬってあります。',null,['白','しろ']);
  add('weather','basic','空全体を10としたとき、雲の量が0〜8のときの天気は、何ですか。','晴れ',['くもり','雨','雪'],['雲が、少ないときです。','雲の量が、9〜10だと、くもりです。'],'雲の量が0〜8のときは晴れ、9〜10のときはくもりです。',null,['晴れ','はれ']);
  add('weather','basic','空全体を10としたとき、雲の量が9〜10のときの天気は、何ですか。','くもり',['晴れ','雨','雪'],['雲が、空をほとんどおおっているときです。','雲の量が、0〜8だと、晴れです。'],'雲の量が9〜10のときは、くもりです。',null,['くもり','曇り']);
  add('weather','basic','気温を表すときに使う、単位は、何ですか。','℃（度）',['m','g','L'],['天気予報でも、聞くことばです。','たとえば、「25 ○」と書きます。'],'気温の単位は、℃（度）です。',null,['℃','度','ど','せっし','セルシウス度']);
  add('weather','basic','晴れた日、1日のうちで気温がいちばん低いのは、いつごろですか。','明け方（日の出のころ）',['昼ごろ','午後2時ごろ','夕方'],['夜の間に、地面は冷えます。','太陽が出る前後です。'],'晴れた日は、夜の間に地面が冷えるので、気温は明け方（日の出のころ）にいちばん低くなります。');
  add('weather','basic','気温をはかる道具の名前は、何ですか。','温度計',['時計','ものさし','はかり'],['温度を、はかる道具です。','中に、赤い液が、入っています。'],'気温は、温度計ではかります。',null,['温度計','おんどけい']);

  add('weather','standard','晴れた日、気温がいちばん高くなるのは、太陽がいちばん高い正午ごろより、前と後の、どちらですか。','後',['前','同じ時刻','決まっていない'],['太陽が、地面をあたため、地面が、空気をあたためます。','気温の上がり方は、少しおくれます。'],'地面があたまり、その熱で空気があたたまるので、気温が高くなるのは、正午ごろより後（午後2時ごろ）です。',null,['後','あと','正午より後','午後']);
  add('weather','standard','晴れの日と雨の日で、1日の気温の変化が、大きいのは、どちらですか。','晴れの日',['雨の日','どちらも同じ','どちらも変化しない'],['晴れた日は、日光が、地面をあたためます。','雨の日は、雲が日光をさえぎります。'],'晴れの日は、日光で気温が大きく上がり、夜は下がるので、変化が大きいです。雨の日は、変化が小さいです。',null,['晴れの日','はれのひ','晴れ','はれ']);
  add('weather','standard','ある日の、気温を、3時間ごとにはかったら、9時が15℃、12時が20℃、15時が22℃、18時が17℃でした。この日の最高気温は、何℃ですか。',22,[15,20,17],['はかった中で、いちばん高い気温です。','4つの気温を、くらべます。'],'はかった気温のなかで、いちばん高いのは15時の22℃です。');
  add('weather','standard','ある日の、最高気温が25℃、最低気温が15℃でした。1日の気温の差は、何℃ですか。',10,[40,25,15],['最高気温から、最低気温を、引きます。','25－15を計算します。'],'25－15＝10。気温の差は10℃です。');
  add('weather','standard','雲の量が8のとき、天気は、何ですか。','晴れ',['くもり','雨','雪'],['雲の量が、0〜8のときは、晴れです。','雲の量が9〜10のときは、くもりです。'],'雲の量が0〜8のときは晴れなので、雲の量が8のときも晴れです。',null,['晴れ','はれ']);
  add('weather','standard','雲の量が9のとき、天気は、何ですか。','くもり',['晴れ','雨','雪'],['雲の量が、9〜10のときは、くもりです。','空のほとんどが、雲におおわれています。'],'雲の量が9〜10のときは、くもりです。',null,['くもり','曇り']);
  add('weather','standard','日なたと日かげで、同じ時刻の地面の温度を比べると、どうなりますか。','日なたのほうが高い',['日かげのほうが高い','どちらも同じ','日なたのほうが低い'],['日光が、直接地面に当たると、どうなりますか。','地面の温度と、日光の関係を、考えます。'],'日光が直接当たる日なたの地面のほうが、日かげの地面より温度が高くなります。');
  add('weather','standard','雨の日の、1日の気温の変化を表す折れ線グラフは、どのような形になりますか。','ほぼ平ら（変化が小さい）',['大きく山形になる','ぎざぎざ','右下がりに、ずっと下がる'],['雨の日は、日光が、地面をあたためません。','晴れの日と、くらべましょう。'],'雨の日は、気温の変化が小さいので、折れ線グラフはほぼ平らになります。');
  add('weather','standard','気温を、はかるとき、温度計を、日光に当てないのは、なぜですか。','温度計が、直接あたたまり、正しい気温がはかれないから',['温度計が、こわれるから','目もりが、見にくいから','風で、ゆれるから'],['空気の温度をはかります。','温度計そのものが、あたたまると、どうなりますか。'],'日光が当たると温度計そのものが熱くなり、空気の温度より高くはかってしまうので、日かげではかります。');
  add('weather','standard','気温を、1日のうちに、何度かはかって、折れ線グラフに表すと、何がわかりますか。','気温の変化のようす',['天気だけ','風の強さ','雲の形'],['グラフの形から、読み取れることです。','時間とともに、どうかわりますか。'],'折れ線グラフにすると、1日の気温の変化のようすがわかります。');
  add('weather','standard','夜から朝にかけて、気温が、下がっていくのは、なぜですか。','太陽がなく、地面が、冷えていくから',['風が、強くなるから','雲が、なくなるから','雨が、ふるから'],['夜は、太陽が出ていません。','地面は、日中にたくわえた熱を、はなします。'],'夜は太陽の光がなく、地面の熱がにげていくので、気温が下がります。');
  add('weather','standard','1日の気温の変化が、ほとんどない日は、どのような天気の日が多いですか。','雨やくもりの日',['よく晴れた日','風がまったくない日','雪が、ふっていない日'],['雲は、日光をさえぎります。','夜も、地面が冷えにくいです。'],'雨やくもりの日は、日光が地面に届きにくく、夜も地面が冷えにくいため、気温の変化が小さいです。');
  add('weather','standard','雲が厚く空をおおうと、昼の気温は、どうなりますか。','上がりにくい',['すぐに上がる','大きく下がる','かわらない'],['雲は、日光を、さえぎります。','晴れの日と、くらべます。'],'雲が厚いと、日光が地面に届きにくいので、昼の気温は上がりにくくなります。',null,['上がりにくい','あがりにくい']);

  add('weather','advanced','午前6時の気温が12℃、午後2時の気温が24℃でした。気温の差は、何℃ですか。',12,[24,36,6],['大きいほうから、小さいほうを引きます。','24－12を計算します。'],'24－12＝12。気温の差は12℃です。');
  add('weather','advanced','ある日の、気温が、6時は10℃、9時は14℃、12時は18℃、15時は20℃でした。6時から15時の間に、気温は、何℃上がりましたか。',10,[20,18,6],['はじめと、おわりの気温を、くらべます。','20－10を計算します。'],'20－10＝10。気温は、10℃上がりました。');
  add('weather','advanced','天気予報で、「最高気温は10℃、最低気温は−2℃」と言っていました。この日の、気温の差は、何℃ですか。',12,[8,10,2],['最低気温が、０℃より低いときです。','10－(−2) を計算します。'],'最高気温10℃と、最低気温−2℃の差は、10＋2＝12℃です。');
  add('weather','advanced','午後2時ごろに、気温が最高になる理由として、正しいものは、どれですか。','地面があたたまり、その熱で空気があたたまるのに、時間がかかるから',['太陽が、この時刻にいちばん高いから','風が、この時刻にいちばん強いから','雲が、この時刻になくなるから'],['太陽が、いちばん高くなるのは、正午ごろです。','熱は、すぐに空気には、つたわりません。'],'太陽がいちばん高い正午ごろから少しおくれて、地面からの熱で空気があたたまり、午後2時ごろに気温が最高になります。');
  add('weather','advanced','気温を、はかるとき、風通しのよい日かげを選ぶのは、何のためですか。','日光や地面の熱のえいきょうを、うけないようにするため',['温度計を、守るため','見やすくするため','雨に、ぬれないようにするため'],['気温は、空気の温度です。','温度計が、あたたまると、どうなりますか。'],'日光や地面の熱のえいきょうをうけると、空気の温度より高くはかってしまうので、風通しのよい日かげではかります。');
  add('weather','advanced','気温の折れ線グラフを、くらべたら、Aの日は山が大きく、Bの日は平らでした。Aの日の天気として、考えられるのは、何ですか。','晴れ',['雨','くもり','雪'],['気温の変化が、大きい日は、どんな日ですか。','日光が、地面をあたためます。'],'気温の変化が大きいAの日は、よく晴れた日と考えられます。Bの日は、雨やくもりの日と考えられます。',null,['晴れ','はれ']);
  add('weather','advanced','雲の量が10のとき、空は、どのようになっていますか。','雲で、全部おおわれている',['雲が、1つもない','雲が、半分ある','雲は、見えない'],['空全体を10としたとき、雲の量が10です。','くもりの天気です。'],'雲の量が10のとき、空全体が雲でおおわれています。');
  add('weather','advanced','気温を、地面近くと、高さ1.2mで、はかりました。日なたで、昼に比べたとき、温度が高いのは、どちらですか。','地面近く',['高さ1.2m','どちらも同じ','比べられない'],['地面が、日光で、あたためられています。','地面近くは、地面の熱の、えいきょうを受けます。'],'日なたの昼は、地面があたためられるため、地面近くのほうが高さ1.2mより温度が高くなります。');
  add('weather','advanced','最高気温が30℃以上の日を、何といいますか。','真夏日',['夏日','猛暑日','冬日'],['最高気温の、目安のことばです。','25℃以上は「夏日」です。'],'最高気温が30℃以上の日を、真夏日といいます。25℃以上は夏日、35℃以上は猛暑日です。',null,['真夏日','まなつび']);
  add('weather','advanced','天気を決めるときに、使わないものは、何ですか。','気温',['雨','雪','雲の量'],['天気は、空のようすで決めます。','雨や雪が、ふっていると、天気は、どうなりますか。'],'天気は、雲の量と、雨や雪などの降りものによって決めます。気温は、天気ではありません。');
  add('weather','advanced','毎日、同じ時刻に、同じ場所で、気温を、はかるのは、何のためですか。','気温を、くらべるため',['温度計を、きたえるため','天気を、きめるため','雨を、ふらせるため'],['条件を、そろえると、どうなりますか。','日によるちがいを、調べたいです。'],'同じ条件ではかると、気温の変化を正しくくらべることができます。');
  add('weather','advanced','晴れた日の昼間、運動場の地面の温度が、気温より高くなることがあります。その理由は、何ですか。','日光で地面があたためられるから',['風で、地面があたたまるから','雲で、地面があたたまるから','雨で、地面があたたまるから'],['太陽の光は、地面に当たります。','地面は、日光を受けて、どうなりますか。'],'晴れた日の昼間は、日光を受けて地面があたためられるため、地面の温度が気温より高くなることがあります。');

  // ---- 雨水のゆくえ：基礎9・標準13・発展12（原作の2問を合わせて 9/15/12）----
  add('rain','basic','雨がふったあと、校庭で、水たまりができやすいのは、地面の高いところと低いところの、どちらですか。','低いところ',['高いところ','どちらも同じ','水たまりはできない'],['水は、高いところから、低いところへ流れます。','低いところに、水が集まります。'],'水は、高いところから低いところへ流れて集まるので、低いところに水たまりができやすいです。',null,['低いところ','ひくいところ','低い所','低い']);
  add('rain','basic','すなとどろでは、水が速くしみこむのは、どちらですか。','すな',['どろ','どちらも同じ','どちらもしみこまない'],['つぶが大きいほうが、すきまが大きいです。','すなのつぶは、どろより、大きいです。'],'すなはつぶが大きく、すきまが多いので、水が速くしみこみます。',null,['すな','砂']);
  add('rain','basic','土のつぶが、大きいほど、水のしみこみ方は、どうなりますか。','速くなる',['おそくなる','かわらない','しみこまなくなる'],['つぶが大きいと、すきまも大きいです。','しみこみやすさを、考えます。'],'つぶが大きいほど、すきまが大きいので、水は速くしみこみます。',null,['速くなる','はやくなる','しみこみやすい','しみこみやすくなる']);
  add('rain','basic','地面にしみこんだ雨水は、どこへいきますか。','地面の下',['空の上','雲の中','木の上'],['しみこんだ水は、下へ下へと進みます。','地面の下に、たまります。'],'地面にしみこんだ雨水は、地面の下へ進み、地下水になることもあります。',null,['地面の下','じめんのした','地下','地下水']);
  add('rain','basic','校庭の水たまりが、日がたつと、なくなっていくのは、水がどうなるからですか。','蒸発して水蒸気になるから',['土になるから','氷になるから','雲になるから'],['水が、すがたをかえて、空気中へ出ていきます。','水たまりの水は、水面から、すがたをかえます。'],'水たまりの水は、蒸発して水蒸気になり、空気中へ出ていくので、少しずつへっていきます。');
  add('rain','basic','屋根にふった雨水は、何を通って、地面へ流れますか。','とい',['かべ','道路','木'],['屋根のはしについている、水の通り道です。','雨どいとも、いいます。'],'屋根にふった雨水は、といを通って、地面へ流れていきます。',null,['とい','雨どい','あまどい']);
  add('rain','basic','つぶが小さくて、かたくしまった土（ねんど）に、水を流すと、水は、どうなりますか。','しみこみにくい',['よくしみこむ','すぐ消える','かわらない'],['つぶが小さいと、すきまも小さいです。','水たまりが、できやすいです。'],'つぶが小さい土は、すきまが小さいので、水がしみこみにくく、水たまりができやすいです。',null,['しみこみにくい','しみこみにくくなる']);
  add('rain','basic','水の流れる向きを、調べるために、やることは、どれですか。','地面に水を流して、流れる向きを見る',['地面をたたく','地面をほる','地面をふむ'],['水がどちらに流れるかを、直接見ます。','少量の水を、流します。'],'地面に水を流して、水が流れる向きを見ると、地面の高さのちがいがわかります。');
  add('rain','basic','水は、どのように流れますか。','高いところから低いところへ',['低いところから高いところへ','決まった向きはない','ななめには流れない'],['雨水が流れて集まる場所は、どこですか。','斜面で、水を流してみると、わかります。'],'水は、高いところから低いところへ流れます。');

  add('rain','standard','雨の日、運動場の水の流れを調べたら、校舎のほうから、反対側のほうへ流れていました。運動場は、どちら側が、高くなっていますか。','校舎のほう',['反対側','どちらも同じ','どちらも低い'],['水は、高いところから、低いところへ流れます。','水が流れてくる側が、高いです。'],'水は高いところから低いところへ流れるので、水が流れてきた校舎のほうが高くなっています。');
  add('rain','standard','つぶの大きさがちがう、すなとどろに、同じ量の水を流しました。水が、すっかりしみこむまでの時間が、長いのは、どちらですか。','どろ',['すな','どちらも同じ','どちらも同じ速さ'],['つぶが小さいと、水のしみこみ方は、どうなりますか。','すなは、つぶが大きいです。'],'どろはつぶが小さく、すきまも小さいので、水がしみこみにくく、時間が長くかかります。',null,['どろ','泥']);
  add('rain','standard','土の、つぶの大きさを、比べるとき、条件をそろえる、ものは、どれですか。','水の量、土の量、容器の大きさ',['土の色','かける時間だけ','季節'],['同じ条件で、比べると、どうなりますか。','かえるのは、土のつぶの大きさだけです。'],'比べるときは、水の量・土の量・容器の大きさなどを同じにして、土のつぶの大きさだけをかえます。');
  add('rain','standard','雨がふった日、水たまりが、できやすい場所は、どのような所ですか。','低くて、水がしみこみにくい所',['高くて、水がしみこみやすい所','高くて、かわいた所','木の下'],['水は、低いところに集まります。','しみこみにくいと、水が残ります。'],'水は低いところに集まり、しみこみにくい土だと、水が残って水たまりになります。');
  add('rain','standard','水がしみこんだあとの、土の色は、しみこむ前と比べて、どうなりますか。','こくなる（色が、こくなる）',['うすくなる','かわらない','白くなる'],['土が、水をふくむと、どうなりますか。','ぬれた土の色を、思い出しましょう。'],'土は水をふくむと、色がこくなります。');
  add('rain','standard','地面にしみこんだ水が、地下で、たまったものを、何といいますか。','地下水',['雨水','かわ','池'],['地面の下に、ある水です。','井戸の水も、これです。'],'地面にしみこんだ水が、地下にたまったものを、地下水（ちかすい）といいます。',null,['地下水','ちかすい']);
  add('rain','standard','雨水は、地面を流れて、さいごに、どこへ流れていきますか。','川を通って、海へ',['山の上','空','森のおく'],['水は、低いところへ流れます。','いちばん低いところは、どこですか。'],'雨水は、地面を流れたり、地下を通ったりして、川を通って、さいごに海へ流れていきます。');
  add('rain','standard','雨がふっても、水たまりが、できにくい土は、つぶが大きい土と小さい土の、どちらですか。','つぶが大きい土',['つぶが小さい土','どちらも同じ','どちらもできない'],['水がしみこみやすいのは、どちらですか。','しみこむと、水たまりは、できません。'],'つぶが大きい土は水がよくしみこむので、水たまりができにくいです。',null,['つぶが大きい土','つぶが大きい','すな']);
  add('rain','standard','地面のかたむきを、調べるには、何を使うと、よいですか。','水（水を流して、流れを見る）',['温度計','かがみ','はかり'],['水が流れる向きを、見ます。','地面のかたむきが、水の流れでわかります。'],'地面に水を流して、その流れる向きを見ると、地面がどちらにかたむいているかがわかります。');
  add('rain','standard','校庭に、すなをまくと、雨のあと、水たまりが、できにくくなることがあります。これは、どうしてですか。','すなには、水がしみこみやすいから',['すなが、水を、はじくから','すなが、水に、とけるから','すなが、水を、ふやすから'],['すなは、つぶが大きいです。','しみこみやすさを、考えます。'],'すなは、つぶが大きくて水がしみこみやすいので、すなをまくと水たまりができにくくなります。');
  add('rain','standard','校庭の土と、花だんのふかふかの土では、水がしみこみやすいのは、どちらですか。','花だんのふかふかの土',['校庭のかたい土','どちらも同じ','どちらもしみこまない'],['ふかふかの土は、つぶの間に、すきまが多いです。','かたい土は、すきまが、少ないです。'],'ふかふかの土は、つぶの間のすきまが多いので、水がしみこみやすいです。');
  add('rain','standard','水を、土にしみこませるとき、水が、早くしみこむ土は、水を通すすきまが、大きいですか、小さいですか。','大きい',['小さい','同じ','すきまはない'],['つぶが大きいと、すきまは、どうなりますか。','水が通るすきまの、大きさを、考えます。'],'水が早くしみこむ土は、つぶが大きく、水が通るすきまも大きいです。',null,['大きい','おおきい']);
  add('rain','standard','雨水が、一度地面にしみこんで、また、わき出してくるものは、どれですか。','わき水（いずみ）',['雲','雨','雪'],['しみこんだ水が、地面の下を、進みます。','山のふもとなどに、あります。'],'地面にしみこんだ水が、地面の下を通って、再び地上へわき出したものが、わき水（いずみ）です。');

  add('rain','advanced','同じ量の水を、すなとどろに、流しました。すなに流した水が、30秒で、すべてしみこみ、どろに流した水が、3分でしみこみました。どろがしみこむのにかかった時間は、すなの何倍ですか。',6,[3,10,30],['3分は、何秒ですか。','180秒÷30秒を、計算します。'],'3分＝180秒。180 ÷ 30＝6。どろは、すなの6倍の時間がかかりました。');
  add('rain','advanced','地面に、雨水が流れた、あとがありました。流れた向きを、調べると、「校舎の北」から「校舎の南」へ、流れていました。地面の高い方は、どちらですか。','北',['南','東','西'],['水は、高いほうから、低いほうへ流れます。','流れ出した方向が、高いです。'],'水は高いところから低いところへ流れるので、流れ出した北のほうが高く、南が低いです。',null,['北','きた']);
  add('rain','advanced','校庭の同じ場所に、雨水が集まるのは、その場所が、どのような場所だからですか。','まわりより低い場所だから',['まわりより高い場所だから','日なたの場所だから','かわいた場所だから'],['水は、どちらへ流れますか。','集まる場所の、高さを、考えます。'],'水は、高いところから低いところへ流れるので、まわりより低い場所に雨水が集まります。');
  add('rain','advanced','雨水の流れる向きを調べるため、校庭に、水を流し、色を付けて、流れの道すじを見やすくします。何を使うと、よいですか。','ふつうの絵の具などで色をつけた水',['砂糖水','ひも','氷'],['流れる水の道すじが、見えるようにします。','色が、ついた水が、わかりやすいです。'],'色を付けた水を流すと、水の流れる向きや道すじが、見やすくなります。');
  add('rain','advanced','運動場に、雨水がたまりやすい場所があります。この場所を、水がたまりにくくするために、すなを入れるのは、なぜですか。','水が、しみこみやすくなるから',['水が、集まるから','水が、蒸発するから','水が、にごるから'],['すなは、つぶが大きいです。','すきまが、大きいと、水が通りやすいです。'],'すなを入れると、すきまが大きくなって水がしみこみやすくなるので、水がたまりにくくなります。');
  add('rain','advanced','雨水の、流れ方を考えるとき、水が流れていく向きと、地面の何が関係していますか。','地面の高さ（かたむき）',['地面の色','地面のかたさだけ','地面の広さだけ'],['水は、どちらに流れますか。','高さが、ちがうと、流れる向きが、ちがいます。'],'水の流れる向きは、地面の高さ（かたむき）で決まります。水は高いところから低いところへ流れます。');
  add('rain','advanced','ある土に、水をかけても、水は、ほとんどしみこまず、地面の上に、のこっていました。この土は、つぶが大きい土と、小さい土の、どちらだと考えられますか。','つぶが小さい土',['つぶが大きい土','どちらも考えられる','土ではない'],['つぶの大きさと、しみこみやすさの関係を、考えます。','水が、すきまを通れませんでした。'],'水がしみこまず、残っていたのは、つぶが小さくてすきまが小さい土だと考えられます。');
  add('rain','advanced','雨がやんだ後、水たまりの水が、へっていく原因は、2つあります。1つは、地面にしみこむこと、もう1つは、何ですか。','蒸発する',['雲になる','氷になる','土になる'],['水が、水蒸気になって、空気中へ出ていくことです。','水面から、起こります。'],'水たまりの水は、地面にしみこむことと、蒸発して水蒸気になることで、少しずつへっていきます。',null,['蒸発する','蒸発','じょうはつ']);
  add('rain','advanced','雨が、ふり続くと、川の水の量は、どうなりますか。','ふえる',['へる','かわらない','なくなる'],['雨水は、川へ流れこみます。','山や、地面の水が、集まります。'],'雨がふり続くと、雨水が川に流れこんで、川の水の量がふえます。',null,['ふえる','増える']);
  add('rain','advanced','土のつぶの大きさと、水のしみこみやすさを調べる実験で、いちばん、水が速くしみこむのは、何ですか。','すな',['どろ','ねんど','水そうの底の土'],['つぶが、大きいものは、どれですか。','つぶの大きさと、すきまの関係を、考えます。'],'すな、どろ、ねんどのうち、つぶがもっとも大きいすなが、いちばん水が速くしみこみます。',null,['すな','砂']);
  add('rain','advanced','雨水を、ためるために、校庭の一部を、低くしました。この場所に、雨水が集まりやすいのは、なぜですか。','水は低いところに流れるから',['水は高いところに流れるから','水は動かないから','水はにげるから'],['水は、高いところから、低いところへ流れます。','低くした場所に、水が集まります。'],'水は高いところから低いところへ流れるので、低くした場所に雨水が集まります。');
  add('rain','advanced','地面のかたむきと、水の流れを調べるとき、斜面の上から水を流し、下に集まるようすを、見ます。この実験で、わかることは、何ですか。','水が、高いところから、低いところへ流れること',['水が、しみこまないこと','水が、あたたまること','水が、軽いこと'],['水は、どちらへ流れますか。','斜面の上と、下を、比べます。'],'斜面で水を流すと、水が高いところから低いところへ流れて、下に集まることがわかります。');

