  add('body','basic','クラゲやタコのように、骨をもたない動物は、体のつくりが、どうなっていますか。','やわらかい',['かたい','とげがある','羽がある'],['骨がないと、体は、どうなりますか。','骨は、体を支えるものです。'],'クラゲやタコのように骨をもたない動物は、体がやわらかいつくりをしています。');
  add('body','basic','人が、うでや足を動かすとき、骨と、何がいっしょにはたらきますか。','筋肉と関節',['血と涙','髪の毛','つめ'],['骨だけでは、動けません。','ちぢんだり、ゆるんだりするものがあります。'],'人は、骨・筋肉・関節がいっしょにはたらくことで、体を動かします。');

  add('body','standard','筋肉は、ちぢむと、どうなりますか。','かたくて、太くなる',['やわらかくなる','細くなる','かわらない'],['力こぶを、つくったときを、思い出しましょう。','うでを曲げたとき、内側の筋肉は、どうなりますか。'],'筋肉は、ちぢむと、かたくなって太くなります。力こぶが、できるのは、そのためです。');
  add('body','standard','うでを、のばすとき、うでの外側の筋肉は、どうなりますか。','ちぢむ',['ゆるむ','かわらない','動かない'],['うでを曲げるとき、内側の筋肉は、ちぢみました。','のばすときは、反対です。'],'うでをのばすときは、外側の筋肉がちぢみ、内側の筋肉がゆるみます。',null,['ちぢむ','縮む']);
  add('body','standard','うでを曲げたとき、うでの外側の筋肉は、どうなりますか。','ゆるむ',['ちぢむ','かわらない','動かない'],['曲げるときは、内側の筋肉が、ちぢみました。','外側は、反対です。'],'うでを曲げるときは、内側の筋肉がちぢみ、外側の筋肉がゆるみます。',null,['ゆるむ']);
