  add('body','standard','うでを曲げたとき、力こぶができる場所は、うでの内側と外側の、どちらですか。','内側',['外側','どちらも','できない'],['うでを曲げるとき、ちぢむのは、どちらの筋肉ですか。','ちぢむと、かたくふくらみます。'],'うでを曲げると、内側の筋肉がちぢんでふくらみ、力こぶができます。',null,['内側','うちがわ']);
  add('body','standard','ひじやひざのように、骨と骨のつなぎ目で、曲げのばしできる、ところには、何がありますか。','関節',['ひふ','つめ','血管'],['骨と骨のつなぎ目です。','動かせる、ところです。'],'骨と骨のつなぎ目で、曲げのばしできるところには、関節があります。',null,['関節','かんせつ']);
  add('body','standard','手の指が、細かく動かせるのは、指に、何がたくさんあるからですか。','関節',['骨だけ','ひふだけ','血だけ'],['指は、曲がります。','動かせる場所は、骨と骨のつなぎ目です。'],'指には関節がたくさんあるので、細かく動かすことができます。',null,['関節','かんせつ']);
  add('body','standard','子どもの骨は、成長すると、どうなりますか。','大きく、じょうぶになる',['小さくなる','かわらない','なくなる'],['体は、成長します。','骨も、成長します。'],'子どもの骨は、成長とともに、大きく、じょうぶになります。');
  add('body','standard','運動をして、体をよく動かすと、筋肉は、どうなりますか。','強くなる',['弱くなる','なくなる','かわらない'],['体をよく動かすと、どうなりますか。','筋肉は、使うほど、どうなりますか。'],'体をよく動かすと、筋肉は、強くなります。',null,['強くなる','つよくなる']);
  add('body','standard','頭の骨は、たくさんの骨が、組み合わさっています。頭の骨は、うでの骨のように、よく動きますか。','ほとんど動かない',['よく動く','自由に動く','かたくて、動かない'],['脳を守る骨は、かたいです。','関節が、あまりありません。'],'頭の骨は、脳を守るため、しっかり組み合わさっていて、ほとんど動きません。');
  add('body','standard','骨・筋肉・関節のうち、骨と骨をつなぐ、動かせる部分は、何ですか。','関節',['筋肉','血管','皮ふ'],['曲げのばしするところです。','ひじやひざが、そうです。'],'骨と骨をつなぐ、動かせる部分を関節といいます。',null,['関節','かんせつ']);
  add('body','standard','ウサギや犬のような動物も、人と同じように、体を動かすために、骨と、何がいっしょにはたらきますか。','筋肉と関節',['血だけ','毛だけ','つめだけ'],['人と、体のつくりは、にています。','骨だけでは、動けません。'],'ウサギや犬のような、骨をもつ動物も、骨・筋肉・関節が、いっしょにはたらいて動きます。');
  add('body','standard','ひざを、曲げたり、のばしたりできるのは、ひざに、何があるからですか。','関節',['ひふ','つめ','血管'],['骨と骨のつなぎ目です。','曲がるところには、何がありますか。'],'ひざには関節があるので、骨を曲げたりのばしたりできます。',null,['関節','かんせつ']);
  add('body','standard','筋肉は、ちぢんだり、ゆるんだりして、何を動かしますか。','骨',['血','皮ふ','髪の毛'],['筋肉は、骨にくっついています。','ちぢむと、骨は、どうなりますか。'],'筋肉がちぢんだりゆるんだりして、骨を動かします。',null,['骨','ほね']);

  add('body','advanced','うでを曲げのばしするとき、内側の筋肉と、外側の筋肉は、どのようにはたらきますか。','一方がちぢむとき、もう一方はゆるむ',['両方いっしょにちぢむ','両方いっしょにゆるむ','どちらも、動かない'],['曲げるときと、のばすときで、はたらく筋肉が、ちがいます。','ペアになって、はたらいています。'],'うでを曲げのばしするとき、2つの筋肉は、一方がちぢむと、もう一方がゆるむように、ペアではたらきます。');
  add('body','advanced','人が、立っていることができるのは、何と何が、体を支えているからですか。','骨と筋肉',['血とひふ','髪とつめ','目と耳'],['骨は、体を支えます。','筋肉は、骨と、いっしょにはたらきます。'],'骨が体を支え、筋肉が骨を引いて動かすので、人は、立ったり歩いたりすることができます。');
  add('body','advanced','ひざを曲げたとき、ひざの関節で、動いているのは、どこですか。','太ももの骨とすねの骨',['ひざのひふ','ふくらはぎの筋肉だけ','足のつめ'],['関節は、骨と骨のつなぎ目です。','ひざの上と下の骨です。'],'ひざの関節は、太ももの骨とすねの骨がつながっているところで、ここで足が曲がります。');
  add('body','advanced','手を、強くにぎったとき、うでの内側と外側のどちらの筋肉が、かたくなりますか。','両方',['内側だけ','外側だけ','どちらも、かたくならない'],['強く、にぎると、うでに力が入ります。','うでを、固定するときは、どうなりますか。'],'手を強くにぎるときは、うでを固定するために、内側と外側の両方の筋肉に力が入ります。');
  add('body','advanced','骨の、はたらきの組み合わせとして、正しいものは、どれですか。','体を支える・体を守る',['体を温める・食べ物を消化する','においをかぐ・音を聞く','血を送る・息をする'],['骨は、かたいものです。','頭の骨と、ろっ骨を、思い出しましょう。'],'骨のはたらきは、体を支えることと、脳や心臓などの大切な部分を守ることです。');
  add('body','advanced','骨と骨をつなぐ関節がなかったら、体は、どうなりますか。','曲げのばしができない',['体が軽くなる','骨が、のびる','筋肉が、ふえる'],['関節は、曲がるところです。','関節が、ないと、うでは、曲がりません。'],'関節がないと、骨が曲がらないので、体を曲げのばしすることができません。');
  add('body','advanced','人の体で、骨の数が、いちばん多いのは、手や足のどこの、あたりですか。','手や足の先',['頭','むね','せなか'],['手の指は、細かく動きます。','指には、小さな骨が、たくさんあります。'],'手や足の先には、小さな骨がたくさんあります。そのため、細かい動きができます。');
  add('body','advanced','筋肉が、ちぢむとき、筋肉の、どこが、骨を動かしますか。','骨にくっついている部分',['血管','髪','皮ふ'],['筋肉は、骨に、くっついています。','ちぢむと、骨が、ひっぱられます。'],'筋肉は、骨にくっついていて、ちぢむと、その部分で骨を引っぱって動かします。');
  add('body','advanced','ひじを曲げたときの、骨・筋肉・関節の、はたらき方の説明として、正しいものは、どれですか。','筋肉がちぢんで、骨を引き、関節で曲がる',['関節がちぢんで、骨を引く','骨が、ちぢんで、筋肉が曲がる','筋肉が、関節を、おさえて、動かさない'],['ちぢむのは、筋肉です。','曲がる場所は、関節です。'],'筋肉がちぢんで骨を引き、関節の部分で骨が動いて曲がります。');
  add('body','advanced','骨が折れやすいのは、骨に、何が足りないときですか。','カルシウム',['鉄分','ビタミンだけ','水だけ'],['骨は、じょうぶにするための、ものがあります。','牛乳や小魚に、多くふくまれています。'],'骨をじょうぶにするには、カルシウムが必要です。牛乳や小魚には、カルシウムが多くふくまれています。',null,['カルシウム','かるしうむ']);
  add('body','advanced','体を動かすとき、骨と筋肉と関節の、うち、「うでをのばす」といった動きに、直接関係しないものは、どれですか。','においをかぐこと',['骨','筋肉','関節'],['体を動かすために、はたらくものを選びます。','においは、鼻で、かぎます。'],'うでをのばすには、骨・筋肉・関節がはたらきます。においをかぐことは、動きとは関係ありません。');

